float vrchPenHash(vec2 point) {
  return fract(sin(dot(point, vec2(27.17, 91.63))) * 15731.743);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 pixelStep = vec2(1.5) / iResolution.xy;
  vec4 image = vrchSampleSource0(uv);
  vec3 leftColor = vrchSampleSource0(uv - vec2(pixelStep.x, 0.0)).rgb;
  vec3 rightColor = vrchSampleSource0(uv + vec2(pixelStep.x, 0.0)).rgb;
  vec3 downColor = vrchSampleSource0(uv - vec2(0.0, pixelStep.y)).rgb;
  vec3 upColor = vrchSampleSource0(uv + vec2(0.0, pixelStep.y)).rgb;
  float luma = dot(image.rgb, vec3(0.2126, 0.7152, 0.0722));
  float edgeStrength = length(rightColor - leftColor) + length(upColor - downColor);
  vec2 point = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float motionWave = sin(iTime * (0.45 + uParam_motion * 0.8));
  float angle = (uParam_direction + motionWave * uParam_motion * 0.08) * 6.28318530718;
  float travel = iTime * uParam_motion * 1.4;
  vec2 hatchDirection = vec2(cos(angle), sin(angle));
  float hatchA = 0.5 + 0.5 * sin(dot(point, hatchDirection) * uParam_scale * 6.28318530718 + travel);
  float hatchB = 0.5 + 0.5 * sin(dot(point, vec2(-hatchDirection.y, hatchDirection.x)) * uParam_scale * 3.14159265359 - travel * 0.65);
  float grain = vrchPenHash(floor(fragCoord / 1.5));
  float shade = clamp(1.0 - luma, 0.0, 1.0);
  float hatch = mix(hatchA, max(hatchA, hatchB), smoothstep(0.38, 0.82, shade));
  float penValue = edgeStrength * uParam_contrast + shade * hatch * (0.72 + (grain - 0.5) * uParam_roughness);
  float inkMask = smoothstep(0.28, 0.72, penValue);
  vec3 drawing = mix(uParam_paper.rgb, uParam_ink.rgb, inkMask);
  fragColor = vec4(mix(image.rgb, drawing, uParam_amount), image.a);
}
